// C2 Monta o card de aprovação do Telegram (botões inline). Não envia nada.
const chatId = (() => { try { return $env.MKT_TELEGRAM_APPROVER_CHAT_ID; } catch (e) { return undefined; } })() || 'PENDENTE_CHAT_ID';
return $input.all().map(({ json: p }) => {
  const id = p.id || p.piece_id || 'PIECE_ID';
  const esc = s => String(s || '').replace(/[<>&]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c]));
  const text = [`<b>📣 Cytron Marketing — aprovar?</b>`, `<b>${esc(p.title)}</b>`, '', `🎣 ${esc(p.hook)}`, '', `<i>${esc((p.script || '').slice(0, 700))}</i>`, '',
    `Canais: ${(p.target_platforms || []).join(', ')}`, `UTM: <code>${esc(p.utm_campaign)}</code>`, `Gerador: ${esc(p.generator)}`].join('\n').slice(0, 4000);
  const cb = a => `mkt:${a}:${id}`; // callback_data <= 64 bytes (uuid = 36)
  const reply_markup = { inline_keyboard: [[{ text: '✅ Aprovar', callback_data: cb('ok') }, { text: '❌ Rejeitar', callback_data: cb('no') }], [{ text: '✍️ Refazer texto', callback_data: cb('rc') }, { text: '🎬 Refazer mídia', callback_data: cb('rm') }]] };
  return { json: { piece_id: id, telegram: { chat_id: chatId, text, parse_mode: 'HTML', reply_markup, disable_web_page_preview: true },
    approval_log: { company_id: p.company_id, piece_id: id, action: 'submitted', channel: 'telegram', actor: 'n8n', meta: { chat_id_set: chatId !== 'PENDENTE_CHAT_ID' } } } };
});

// C5 Interpreta o callback do Telegram. Valida o secret header e o aprovador. Não grava nada.
const env = k => { try { return $env[k]; } catch (e) { return undefined; } };
const req = $input.first().json; const body = req.body || req; const headers = req.headers || {};
const secret = env('MKT_TELEGRAM_WEBHOOK_SECRET');
const okSecret = !!secret && headers['x-telegram-bot-api-secret-token'] === secret;
const allowed = String(env('MKT_TELEGRAM_APPROVER_IDS') || '').split(',').map(s => s.trim()).filter(Boolean);
const cq = body.callback_query || {}; const from = cq.from || {};
const m = String(cq.data || '').match(/^mkt:(ok|no|rc|rm):([0-9a-f-]{36})$/i);
const MAP = { ok: { action: 'approved', status: 'approved' }, no: { action: 'rejected', status: 'rejected' }, rc: { action: 'regenerate_copy', status: 'draft' }, rm: { action: 'regenerate_media', status: 'draft' } };
let reason = null;
if (!okSecret) reason = 'secret header inválido ou não configurado';
else if (!m) reason = 'callback_data inválido';
else if (!allowed.includes(String(from.id))) reason = 'usuário não autorizado';
const act = m ? MAP[m[1].toLowerCase()] : null;
return [{ json: { valid: !reason, reason, callback_query_id: cq.id || null, piece_id: m ? m[2] : null, action: act?.action || null, new_status: act?.status || null,
  actor: from.username ? '@' + from.username : String(from.id || ''), approval_log: m ? { piece_id: m[2], action: act.action, channel: 'telegram', actor: from.username ? '@' + from.username : String(from.id || ''), meta: { telegram_user_id: from.id || null } } : null } }];
